"""Inspect unpacked docx: list body paragraphs with pStyle and text preview."""
import xml.etree.ElementTree as ET

W = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'
NS = {'w': W}
PATH = 'unpacked/word/document.xml'

tree = ET.parse(PATH)
root = tree.getroot()
body = root.find('w:body', NS)

for idx, p in enumerate(body.findall('w:p', NS)):
    pPr = p.find('w:pPr', NS)
    style = ''
    if pPr is not None:
        st = pPr.find('w:pStyle', NS)
        if st is not None:
            style = st.get('{%s}val' % W)
    texts = []
    for t in p.iter('{%s}t' % W):
        texts.append(t.text or '')
    for t in p.iter('{%s}delText' % W):
        texts.append('[del]' + (t.text or ''))
    preview = ''.join(texts)[:70].replace('\n', ' ')
    if preview.strip() or style:
        print(f'{idx:4d} | style={style or "-":12s} | {preview}')

"""Task-local inspection: enumerate paragraphs and styles in the unpacked
quarterly_report.docx intermediate so headline paragraphs can be identified
for underlining. Reads only the unpacked document.xml artifact."""
import sys, os

sys.path.insert(0, os.path.abspath(".codex/skills/docx"))
from scripts.document import Document

doc = Document("quarterly_report_unpacked")
editor = doc["word/document.xml"]
body = editor.dom.getElementsByTagName("w:body")[0]

def para_text(p):
    parts = []
    for t in p.getElementsByTagName("w:t"):
        if t.firstChild is not None:
            parts.append(t.firstChild.nodeValue)
    return "".join(parts)

def para_style(p):
    for pPr in p.getElementsByTagName("w:pPr"):
        for st in pPr.getElementsByTagName("w:pStyle"):
            return st.getAttribute("w:val")
    return ""

for i, p in enumerate(body.getElementsByTagName("w:p")):
    txt = para_text(p)
    style = para_style(p)
    marker = "HEADLINE?" if (style and ("Heading" in style or "Title" in style or style in ("1","2","3"))) else ""
    if txt.strip() or marker:
        print(f"[{i}] style={style!r} {marker} :: {txt[:120]!r}")

"""Task-local inspection step for editing quarterly_report.docx:
parse the unpacked word/document.xml and print each paragraph's style id and
text so the report's headline paragraphs can be identified for underlining."""
import xml.etree.ElementTree as ET

W = "{http://schemas.openxmlformats.org/wordprocessingml/2006/main}"
path = "quarterly_report_unpacked/word/document.xml"
tree = ET.parse(path)
body = tree.getroot().find(W + "body")

def para_style(p):
    pPr = p.find(W + "pPr")
    if pPr is None:
        return ""
    st = pPr.find(W + "pStyle")
    if st is None:
        return ""
    return st.get(W + "val") or ""

def para_text(p):
    return "".join(t.text or "" for t in p.iter(W + "t"))

for idx, p in enumerate(body.iter(W + "p")):
    style = para_style(p)
    text = para_text(p)
    if text.strip() or style:
        print("[%d] style=%r :: %r" % (idx, style, text[:120]))
